// Idempotencia + memoria de largo plazo (pestaña Sistema_Final, filtrada por email).
const req = $('Normalizar petición + traceId').first().json;
const filas = $input.all().map(i => i.json).filter(r => r && r.request_id);
const previa = filas.find(r => String(r.request_id) === String(req.request_id));
const historial = filas
  .filter(r => String(r.request_id) !== String(req.request_id) && String(r.estado_final || '').startsWith('RESPONDIDO'))
  .slice(-3)
  .map(r => `- ${r.fecha_recepcion}: preguntó "${r.pregunta}" → se respondió: ${String(r.respuesta || '').slice(0, 160)}`)
  .join('\n');
return [{ json: { ...req,
  estado_final: 'EN_PROCESO',
  duplicado: Boolean(previa),
  estado_previo: previa ? previa.estado_final : null,
  memoria: historial || 'Sin consultas previas registradas para este cliente.' } }];

